/**
 * Hezekiah's Crisis
 * -----------------
 * Sennacherib's letters threaten Jerusalem; Hezekiah spreads the letter before the Lord, and the angel strikes the camp. Stage: a royal chamber at night, a letter on a table, the king in prayer; dawn light through the windows, a camp of silent tents beyond the walls.
 *
 * Palette 0x1a2a14 → 0x060402 · light: ember · hero: city
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./isaiah-kit.js.
 */

import { THREE, createScene, column, throne, tent, firepit, cityGate, person } from './isaiah-kit.js';

const BG = 0x1a2a14;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2420770363, bg: BG, fogNear: 45, fogFar: 180 });

    /* light — ember */
    W.lights({ sky: 0x3a2418, gnd: 0x1a0e08, hemi: 0.4, sun: 0xff7a30, sunI: 0.7, sunPos: [20, 26, 30] });

    W.stars(90, 150, [0xf0e0c8, 0xd8c0a0], 0.7);
    W.disc([0, 34, -150], 14, 0xff8a30, 0.12);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x14200f });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x111b0d });

    /* camp: a circle of tents, smoke rising */
    tent(W, group, 5.4, 0, -22.9, 1.15, 0xd8c8a0, W.r() * 6);
    tent(W, group, 24.5, 0, -20.1, 0.90, 0xc8b088, W.r() * 6);
    tent(W, group, -11.5, 0, -22.3, 1.25, 0x8a6a44, W.r() * 6);
    firepit(W, group, -6.2, 0, -4.1, 1.0);

    /* hero: the city gate */
    cityGate(W, group, 0, 0, -8, 1.1, { stone: 0x060402, trim: 0x050302 });

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, bend: 0.12, armR: [2.5, 0.35], armL: [0.3, 0.1], ry: -0.21, s: 1.00 });
    person(W, group, [4.5, 0, 6], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, bend: 0.12, armR: [2.5, 0.35], armL: [0.3, 0.1], ry: 0.26, s: 1.15 });
    person(W, group, [1, 0, -5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, bend: 0.12, armR: [2.5, 0.35], armL: [0.3, 0.1], ry: -0.19, s: 1.10 });

    return W.finish();
}

export default { build };
